python3 << 'EOF'
import re

# Read the file
with open('/app/resources/treasury_bulletin_1970_12_page_44.txt', 'r') as f:
    content = f.read()

# Find the 9-month and one-year section
rows = re.findall(r'<tr><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td></tr>', content)

# Collect all issue dates in the 9-month/12-month category
print("All 9-month and 12-month bills with their amounts maturing on issue date:")
print("="*100)

data = []

for row in rows:
    issue_date, maturity_date, days, tendered, accepted_total, competitive, noncomp, exchange, maturing_on_issue, unmatured = row

    issue_date = issue_date.replace('<br>', ' ').strip()
    days_str = days.replace('<br>', '|').strip()
    maturing_on_issue = maturing_on_issue.replace('<br>', '|').strip()

    # Determine year
    year = None
    if issue_date.startswith('1970-'):
        year = 1970
    elif issue_date.startswith('1969-'):
        year = 1969
    elif 'Dec. 31' in issue_date:
        year = 1969
    elif 'Jan. 31' in issue_date:
        year = 1970
    elif 'Feb.' in issue_date:
        year = 1970
    elif 'Mar.' in issue_date:
        year = 1970
    elif 'Apr.' in issue_date:
        year = 1970
    elif 'May' in issue_date:
        year = 1970
    elif 'June' in issue_date:
        year = 1970
    elif 'July' in issue_date:
        year = 1970
    elif 'Aug.' in issue_date:
        year = 1970
    elif 'Sept.' in issue_date:
        year = 1970
    elif 'Oct.' in issue_date:
        year = 1970
    elif 'Nov.' in issue_date and 'Nov. 30' in issue_date:
        year = 1970

    # Determine month
    month = None
    if 'Nov' in issue_date:
        month = 11
    elif 'Dec' in issue_date:
        month = 12
    elif 'Jan' in issue_date:
        month = 1
    elif 'Feb' in issue_date:
        month = 2
    elif 'Mar' in issue_date:
        month = 3
    elif 'Apr' in issue_date:
        month = 4
    elif 'May' in issue_date:
        month = 5
    elif 'June' in issue_date:
        month = 6
    elif 'July' in issue_date:
        month = 7
    elif 'Aug' in issue_date:
        month = 8
    elif 'Sept' in issue_date:
        month = 9
    elif 'Oct' in issue_date:
        month = 10

    # Check if it's a 9-month or 12-month bill
    is_9_or_12_month = False
    if '273' in days_str or '271' in days_str or '272' in days_str or '274' in days_str or '275' in days_str or '276' in days_str:
        is_9_or_12_month = True
    if '365' in days_str:
        is_9_or_12_month = True

    if is_9_or_12_month:
        # Parse the maturing_on_issue amounts
        amounts = [x.strip() for x in maturing_on_issue.split('|') if x.strip() and x.strip() != '-']
        amounts_numeric = []
        for a in amounts:
            # Remove commas and convert to float
            try:
                amounts_numeric.append(float(a.replace(',', '')))
            except:
                pass

        data.append({
            'issue_date': issue_date,
            'year': year,
            'month': month,
            'days': days_str,
            'amounts': amounts,
            'total': sum(amounts_numeric) if amounts_numeric else 0
        })

# Now filter for Nov 1969 - Feb 1970
# The issue dates we identified:
# Dec 1969: Dec 31
# Jan 1970: Jan 31
# Feb 1970: Feb 2, Feb 28

# Group by calendar month and compute total
print("\nFiltering for Nov 1969 - Feb 1970:")
print("-"*100)

monthly_totals = {}

for d in data:
    if d['year'] == 1969 and d['month'] == 11:
        # Need to check if there's a Nov 1969 issue
        print(f"Nov 1969: {d}")
    elif d['year'] == 1969 and d['month'] == 12:
        monthly_totals['Dec 1969'] = monthly_totals.get('Dec 1969', 0) + d['total']
        print(f"Dec 1969: Issue {d['issue_date']}, Total: {d['total']}")
    elif d['year'] == 1970 and d['month'] == 1:
        monthly_totals['Jan 1970'] = monthly_totals.get('Jan 1970', 0) + d['total']
        print(f"Jan 1970: Issue {d['issue_date']}, Total: {d['total']}")
    elif d['year'] == 1970 and d['month'] == 2:
        monthly_totals['Feb 1970'] = monthly_totals.get('Feb 1970', 0) + d['total']
        print(f"Feb 1970: Issue {d['issue_date']}, Total: {d['total']}")

print("\n" + "="*100)
print("Monthly totals for Nov 1969 - Feb 1970:")
for k, v in monthly_totals.items():
    print(f"  {k}: {v}")

EOF
